codeExercises.solution:
import copy

class InvalidTx(Exception):
    pass

def apply(state, tx):
    """APPLY(S, TX) -> S' oppure errore. state: {addr: {'balance':int,'nonce':int}}.
    tx: dict con from, to, value, nonce, gas_price, gas_used (semplificato: 21000)."""
    s = copy.deepcopy(state)
    snd = s.get(tx["from"])
    if snd is None:
        raise InvalidTx("mittente sconosciuto")
    if tx["nonce"] != snd["nonce"]:
        raise InvalidTx(f"nonce errato: atteso {snd['nonce']}, ricevuto {tx['nonce']}")
    fee = 21_000 * tx["gas_price"]
    if snd["balance"] < tx["value"] + fee:
        raise InvalidTx(f"saldo insufficiente: {snd['balance']} < {tx['value'] + fee}")
    snd["nonce"] += 1
    snd["balance"] -= tx["value"] + fee
    rcv = s.setdefault(tx["to"], {"balance": 0, "nonce": 0})
    rcv["balance"] += tx["value"]
    return s

S = {"Alice": {"balance": 50, "nonce": 5}, "Bob": {"balance": 30, "nonce": 2}}
tx = {"from": "Alice", "to": "Bob", "value": 10, "nonce": 5, "gas_price": 0}
S1 = apply(S, tx)
print("S' =", S1)
# Bob prova a rigiocare la stessa transazione (replay)
try:
    apply(S1, tx)
except InvalidTx as e:
    print("replay rifiutato:", e)
# transazione con nonce saltato
try:
    apply(S1, dict(tx, nonce=7))
except InvalidTx as e:
    print("nonce gap rifiutato:", e)
# saldo insufficiente (slide 49)
try:
    apply(S1, dict(tx, nonce=6, value=70))
except InvalidTx as e:
    print("ERROR:", e)
# con fee reale: gas price 1 (unità arbitrarie) -> 21000 di fee
S2 = apply({"Alice": {"balance": 100_000, "nonce": 0}}, {"from": "Alice", "to": "Bob", "value": 10, "nonce": 0, "gas_price": 1})
print("con fee:", S2)

