import copy

COST = {"PUSH": 3, "ADD": 3, "SUB": 3, "MUL": 5, "LT": 3, "DUP": 3, "SWAP": 3, "POP": 2,
        "JUMP": 8, "JUMPI": 10, "SLOAD": 2100, "SSTORE": 20000, "STOP": 0}

class OutOfGas(Exception):
    pass

def run(program, storage, gas_limit):
    """Esegue il programma; se il gas finisce annulla ogni modifica allo storage."""
    st = copy.deepcopy(storage)          # copia di lavoro: si fa commit solo a fine esecuzione
    stack, pc, gas = [], 0, gas_limit
    while pc < len(program):
        op, *arg = program[pc]
        c = COST[op]
        if gas < c:
            raise OutOfGas(f"out of gas al pc={pc} ({op}), gas usato {gas_limit - gas}")
        gas -= c
        pc += 1
        if op == "PUSH": stack.append(arg[0])
        elif op == "ADD": b, a = stack.pop(), stack.pop(); stack.append(a + b)
        elif op == "SUB": b, a = stack.pop(), stack.pop(); stack.append(a - b)
        elif op == "MUL": b, a = stack.pop(), stack.pop(); stack.append(a * b)
        elif op == "LT": b, a = stack.pop(), stack.pop(); stack.append(int(a < b))
        elif op == "DUP": stack.append(stack[-1])
        elif op == "SWAP": stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == "POP": stack.pop()
        elif op == "JUMP": pc = arg[0]
        elif op == "JUMPI":
            if stack.pop(): pc = arg[0]
        elif op == "SLOAD": stack.append(st.get(stack.pop(), 0))
        elif op == "SSTORE": key = stack.pop(); st[key] = stack.pop()
        elif op == "STOP": break
    return st, gas_limit - gas

# storage[0] = 2 + 3, poi STOP
prog_ok = [("PUSH", 2), ("PUSH", 3), ("ADD",), ("PUSH", 0), ("SSTORE",), ("STOP",)]
# scrive storage[0] = 1, poi ciclo infinito (while true)
prog_loop = [("PUSH", 1), ("PUSH", 0), ("SSTORE",), ("JUMP", 3), ("JUMP", 3)]

storage = {}
new, used = run(prog_ok, storage, 30000)
print("ok: storage", new, "gas usato", used, "rimborso", 30000 - used)
try:
    run(prog_loop, storage, 50000)
except OutOfGas as e:
    print("loop:", e)
    print("storage dopo il revert:", storage)

