from keccak import keccak256  # file keccak.py dell'esercizio 3

def rlp_bytes(b: bytes) -> bytes:
    if len(b) == 1 and b[0] < 0x80:
        return b                                  # un singolo byte piccolo codifica se stesso
    if len(b) <= 55:
        return bytes([0x80 + len(b)]) + b
    lb = len(b).to_bytes((len(b).bit_length() + 7) // 8, "big")
    return bytes([0xb7 + len(lb)]) + lb + b

def rlp_int(n: int) -> bytes:
    # un intero si codifica come stringa big-endian senza zeri iniziali; 0 = stringa vuota
    return rlp_bytes(b"" if n == 0 else n.to_bytes((n.bit_length() + 7) // 8, "big"))

def rlp_list(items) -> bytes:
    payload = b"".join(items)
    assert len(payload) <= 55
    return bytes([0xc0 + len(payload)]) + payload

def contract_address(sender_hex: str, nonce: int) -> str:
    sender = bytes.fromhex(sender_hex.removeprefix("0x"))
    enc = rlp_list([rlp_bytes(sender), rlp_int(nonce)])
    return "0x" + keccak256(enc)[12:].hex()

