// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

// Il contratto bb75a980 del white paper (slide 50-51) e lo "splitter" 892bf92f
contract Registry {
    mapping(uint256 => bytes32) public store;

    // if !storage[key]: storage[key] = value   (accetta anche ether, come la tx di slide 51)
    function set(uint256 key, bytes32 value) external payable {
        if (store[key] == bytes32(0)) {
            store[key] = value;
        }
    }
}

contract Splitter {
    address payable[3] public dest;

    constructor(address payable a, address payable b, address payable c) {
        dest = [a, b, c];
    }

    // riceve ether senza data e lo divide in tre parti
    receive() external payable {
        uint256 part = msg.value / 3;
        for (uint256 i = 0; i < 3; i++) {
            (bool ok, ) = dest[i].call{value: part}("");
            require(ok, "invio fallito");
        }
    }
}

